/* ============================================================
   🎀 全局主题：[ ·天使の心事日記箋 · ] 🎀
   说明：包含透明伪装顶底栏、专属贴纸按键、蕾丝骨翼气泡
   + 包含多选模式智能防遮挡
   ============================================================ */

:root {
   /* ════════════════════════════════════
      1️⃣ 【全局视觉与背景素材】
      ════════════════════════════════════ */
   /* 🌌 全局聊天界面的大背景图 */
   --global-bg-img: url('https://s3plus.meituan.net/opapisdk/op_ticket_1_5677168484_1763778437714_qdqqd_ooj0wr.jpeg');

   /* 🧑‍🤝‍🧑 顶栏中央的字体与用户头像 */
   --avatar-size: 38px;          /* 顶栏头像的大小 */
   --avatar-radius: 50%;         /* 头像的圆角程度 (50%是纯圆) */
   --user-avatar-img: url('https://img.heliar.top/file/1781862723374_IMG_2684.jpeg'); /* 右侧用户的头像图 */

   --title-color: #cbaeb9;       /* 顶栏名字的颜色 (蕾丝粉) */
   --title-size: 16px;           /* 顶栏名字的大小 */
   --subtitle-color: #ffffff;    /* 顶栏底部签名句子的颜色 */
   --subtitle-size: 12px;        /* 顶栏底部签名句子的大小 */


   /* ════════════════════════════════════
      2️⃣ 【顶栏控制台】 (高度、位置、按键)
      ════════════════════════════════════ */
   --header-height: 120px;       /* ↕️ 顶栏整体高度 (决定了防穿透墙有多高) */
   --profile-top: 50px;          /* ↕️ 顶栏中间双头像+名字组合的上下位置 */
   --profile-offset-x: 0px;      /* ↔️ 顶栏中间组合的左右平移 (0 为居中) */

   /* 🎀 顶栏左侧：返回键 */
   --back-btn-left: 10px;        /* ↔️ 返回键离左边的距离 */
   --back-btn-top: -10px;        /* ↕️ 返回键上下微调 */
   --back-icon-img: url('https://img.heliar.top/file/1781864609108_IMG_2690.png'); /* 返回键贴纸 */
   --back-icon-size: 50px;       /* 🔍 返回键贴纸大小 */

   /* 🎀 顶栏右侧：设置键 */
   --info-btn-right: 12px;       /* ↔️ 设置键离右边的距离 */
   --info-btn-top: -30px;        /* ↕️ 设置键上下微调 */
   --info-icon-img: url('https://img.heliar.top/file/1781864612649_IMG_2691.png'); /* 设置键贴纸 */
   --info-icon-size: 55px;       /* 🔍 设置键贴纸大小 */

   /* 📱 隐藏热区：点击头像打电话/视频 */
   --hitbox-top: -35px;           /* 热区整体上下位置 */
   --hitbox-size: 38px;           /* 热区点击范围大小 */
   --phone-hitbox-offset: -262px; /* 电话键热区左右平移量 */
   --video-hitbox-offset: -148px; /* 视频键热区左右平移量 */


   /* ════════════════════════════════════
      3️⃣ 【底栏控制台】 (高度、防遮挡、输入框)
      ════════════════════════════════════ */
   --bottom-bar-height: 100px;   /* ↕️ 底栏防穿透墙的最小高度 */
   --action-bar-bottom: 45px;    /* ↕️ 整个输入框组合距离底部的距离 */

   /* ⌨️ 输入框专属设置 */
   --input-border: 1px solid #FFFFFF; /* ✨ 输入框白色边框 ✨ */
   --input-radius: 20px;              /* 输入框边框的圆角 */
   --input-padding-left: 15px;        /* ↔️ 防挡：文字离左侧边框的距离 */
   --input-padding-right: 45px;       /* ↔️ 防挡：文字离右侧边框的距离 */

   /* 📝 提示文字 (未打字时显示的句子) */
   --custom-placeholder: "⁺․ 𓏴 Cross-engraved heart 𓏴 ․⁺";
   --placeholder-color: #888888; /* 文字颜色：灰色 */
   --placeholder-size: 14px;     /* 文字大小 */
   --placeholder-left: 20px;     /* 文字离左边的距离 */

   /* 🎀 底栏专属挂饰 (最下方那排图案) */
   --bottom-sticker-img: url('https://img.heliar.top/file/1781866609830_无标题77_20260619184925.png');
   --bottom-sticker-width: 350px;  
   --bottom-sticker-height: 50px;  
   --bottom-sticker-bottom: 10px;  /* 距离最底部的距离 */
   --bottom-sticker-offset-x: 0px; 


   /* ════════════════════════════════════
      4️⃣ 【底栏 5 大按键控制台】
      ════════════════════════════════════ */
   /* ➕ 左侧加号键 */
   --btn-plus-img: url('https://img.heliar.top/file/1781867569984_IMG_2709.png');
   --btn-plus-size: 45px;        
   --btn-plus-x: 0px;            
   --btn-plus-y: -40px;            

   /* 🎤 语音键 */
   --btn-mic-img: url('https://img.heliar.top/file/1781867574701_IMG_2710.png');
   --btn-mic-size: 32px;
   --btn-mic-x: 0px;
   --btn-mic-y: 0px;

   /* 😊 表情包键 */
   --btn-sticker-img: url('https://img.heliar.top/file/1781867574582_IMG_2711.png');
   --btn-sticker-size: 32px;
   --btn-sticker-x: 0px;
   --btn-sticker-y: 0px;

   /* ↩️ 默认回复键 (不打字时) */
   --btn-ai-img: url('https://img.heliar.top/file/1781867575713_IMG_2712.png');
   --btn-ai-size: 32px;
   --btn-ai-x: 0px;
   --btn-ai-y: 0px;

   /* 🚀 发送键 (打字时显示) */
   --btn-send-img: url('https://img.heliar.top/file/1781867576026_IMG_2713.png');
   --btn-send-size: 36px;        
   --btn-send-x: 0px;
   --btn-send-y: 0px;


   /* ════════════════════════════════════
      5️⃣ 【消息防遮挡距离设定】
      ════════════════════════════════════ */
   --messages-padding-top: 130px;    /* 聊天记录顶部留白，防止被顶栏挡住 */
   --messages-padding-bottom: 120px; /* 聊天记录底部留白，防止被底栏挡住 */
}

/* ====================================================================
   █ 模块 1：全局背景与防遮挡系统
   ==================================================================== */
/* 注入全局静态背景图 */
body, .chat-detail-screen, #api-chat-screen {
    background-image: var(--global-bg-img) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important; /* 固定背景，滑动消息时背景不动 */
    background-color: transparent !important;
}

/* 强制清理可能自带的渐变或暗色遮罩 */
.chat-detail-screen::after, .chat-detail-screen::before {
    display: none !important;
}

/* 赋予聊天容器上下留白，防止首尾消息陷入顶底栏 */
.chat-messages-area, .chat-messages, .message-list, .scroll-view,
[class*="message-list"], [class*="chat-content"], .messages-container {
    padding-top: var(--messages-padding-top) !important;
    padding-bottom: var(--messages-padding-bottom) !important;
    box-sizing: border-box !important;
    background: transparent !important; 
}


/* ====================================================================
   █ 模块 2：顶栏系统 (防穿透伪装 + 按键与头像排版)
   ==================================================================== */
/* --- 顶栏外壳伪装术 --- */
.chat-header-custom, #api-chat-screen .header {
    position: absolute !important;
    top: 0 !important; left: 0 !important; right: 0 !important;
    height: var(--header-height) !important;
    z-index: 100 !important;

    /* 将顶栏背景设为与全局一样的固定壁纸，实现“看起来透明，其实能挡住滑动消息”的效果 */
    background-image: var(--global-bg-img) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important; 

    border: none !important; box-shadow: none !important;
}

/* --- 顶栏两侧自定义贴纸按键 --- */
.header-btn-back, .header-btn-info {
    position: absolute !important; 
    background-color: transparent !important; border: none !important; box-shadow: none !important;
    width: 45px !important; height: 45px !important; /* 加大热区方便触控 */
    display: flex !important; justify-content: center !important; align-items: center !important;
    z-index: 100 !important;
    background-repeat: no-repeat !important; background-position: center !important;
}
.header-btn-back { 
    left: var(--back-btn-left) !important; top: var(--back-btn-top) !important; 
    background-image: var(--back-icon-img) !important; background-size: var(--back-icon-size) !important;
}
.header-btn-info { 
    right: var(--info-btn-right) !important; top: var(--info-btn-top) !important; 
    background-image: var(--info-icon-img) !important; background-size: var(--info-icon-size) !important;
}
/* 强杀内置原生矢量图标 */
.header-btn-back svg, .header-btn-info svg, .header-btn-back img, .header-btn-info img, .header-btn-back .icon, .header-btn-info .icon {
    display: none !important; 
}

/* --- 隐形热区：打电话和视频键 --- */
.header-btn-phone, .header-btn-video {
    position: absolute !important;
    top: var(--hitbox-top) !important; left: 50% !important; 
    width: var(--hitbox-size) !important; height: var(--hitbox-size) !important;
    border-radius: 50% !important; 
    opacity: 0 !important; /* 完全隐形状态 */
    z-index: 200 !important; padding: 0 !important; margin: 0 !important;
}
.header-btn-phone { transform: translateX(-50%) translateX(var(--phone-hitbox-offset)) !important; }
.header-btn-video { transform: translateX(-50%) translateX(var(--video-hitbox-offset)) !important; }
.header-btn-phone svg, .header-btn-video svg { display: none !important; }

/* --- 顶栏中央双头像对称结构 --- */
.header-profile-section {
    position: absolute !important;
    left: 50% !important; top: var(--profile-top) !important;
    transform: translateX(-50%) translateX(var(--profile-offset-x)) !important; 
    display: flex !important; flex-direction: row !important; 
    align-items: center !important; justify-content: center !important; gap: 12px !important; 
    background: transparent !important; border: none !important; box-shadow: none !important;
    padding: 0 !important; padding-bottom: 24px !important; 
    z-index: 80 !important;
}
/* 左侧对方头像 */
.header-avatar-container {
    width: var(--avatar-size) !important; height: var(--avatar-size) !important;
    border-radius: var(--avatar-radius) !important; margin: 0 !important;
    border: 1.5px solid rgba(255,255,255,0.7) !important; 
    box-shadow: 0 2px 8px rgba(0,0,0,0.1) !important;
    flex-shrink: 0 !important; display: block !important;
}
.chat-header-avatar {
    width: 100% !important; height: 100% !important; border-radius: inherit !important; object-fit: cover !important;
}
/* 中间名字文字 */
.chat-header-title {
    display: flex !important; align-items: center !important; gap: 12px !important; 
    font-size: var(--title-size) !important; color: var(--title-color) !important; font-weight: 600 !important; 
    text-shadow: 0 0 6px rgba(255, 255, 255, 0.9) !important; 
    padding: 0 !important; background: transparent !important; border: none !important;
}
/* 魔法生成：右侧自己头像 */
.chat-header-title::after {
    content: "" !important; display: block !important;
    width: var(--avatar-size) !important; height: var(--avatar-size) !important;
    border-radius: var(--avatar-radius) !important; border: 1.5px solid rgba(255,255,255,0.7) !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1) !important;
    background-image: var(--user-avatar-img) !important; background-size: cover !important; background-position: center !important;
}
.chat-header-subtitle { display: none !important; }

/* 顶栏底部挂接的自定义梦境句子 */
.header-profile-section::after {
    content: "⁺ʚ>𖥦<ɞ⁺讓小貓看看你的夢境" !important;
    position: absolute !important; bottom: 5px !important; left: 50% !important; transform: translateX(-50%) !important;
    white-space: nowrap !important; font-size: var(--subtitle-size) !important; color: var(--subtitle-color) !important;
    font-weight: 500 !important; letter-spacing: 0.5px !important;
    text-shadow: 0 1px 3px rgba(0,0,0,0.4), 0 0 10px rgba(255, 210, 228, 0.9) !important; pointer-events: none !important;
}


/* ====================================================================
   █ 模块 3：底栏系统 (伪装高度、白色边框输入框、动态按键)
   ==================================================================== */
/* --- 底栏外壳伪装与弹性排版 --- */
.input-area-custom, #api-chat-screen .chat-input-area {
    position: absolute !important; bottom: 0 !important; left: 0 !important; right: 0 !important;
    min-height: var(--bottom-bar-height) !important; height: auto !important; z-index: 100 !important;
    display: flex !important; flex-direction: column !important; justify-content: flex-end !important;

    /* 与顶栏同理，铺上固定壁纸实现不穿透的视觉透明 */
    background-image: var(--global-bg-img) !important; background-size: cover !important;
    background-position: center !important; background-repeat: no-repeat !important; background-attachment: fixed !important; 
    border: none !important; box-shadow: none !important;
}
/* 杀掉原生自带伪元素光效 */
.input-area-custom::before, .input-area-custom::after { display: none !important; }

/* --- 注入底栏专属下摆挂饰贴图 --- */
#api-chat-screen .chat-input-area::after, .input-area-custom::after {
    content: "" !important; position: absolute !important;
    bottom: var(--bottom-sticker-bottom) !important; left: 50% !important;
    transform: translateX(-50%) translateX(var(--bottom-sticker-offset-x)) !important;
    width: var(--bottom-sticker-width) !important; height: var(--bottom-sticker-height) !important;
    background-image: var(--bottom-sticker-img) !important; background-size: contain !important;
    background-position: center !important; background-repeat: no-repeat !important;
    pointer-events: none !important; z-index: 10 !important; display: block !important;
}

/* 🌟 解决多选模式遮挡：如果检测到进入多选/复选框状态，立刻隐藏底栏贴纸 🌟 */
.chat-detail-screen:has([class*="selection"]) .input-area-custom::after,
.chat-detail-screen:has([class*="checkbox"]) .input-area-custom::after,
.chat-detail-screen:has(.msg-bubble-wrapper svg) .input-area-custom::after,
#api-chat-screen:has([class*="selection"]) .chat-input-area::after,
#api-chat-screen:has([class*="checkbox"]) .chat-input-area::after,
#api-chat-screen:has(.msg-bubble-wrapper svg) .chat-input-area::after {
    display: none !important;
}

/* --- 输入框行容器定位 --- */
.input-action-bar-custom {
    position: relative !important; 
    margin-bottom: var(--action-bar-bottom) !important; /* 往上推高腾出贴纸空间 */
    width: 100% !important; box-sizing: border-box !important;
    background: transparent !important; padding: 0 12px !important; 
    display: flex !important; align-items: center !important; gap: 8px !important;
}

/* --- ✨带白色边框的隐形输入框本体✨ --- */
.input-box-custom, .chat-input, #api-chat-screen .chat-input {
    background: transparent !important; background-color: transparent !important;

    /* 用户要求的白色边框与圆角设置 */
    border: var(--input-border) !important; 
    border-radius: var(--input-radius) !important; 

    box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; outline: none !important;
    height: 40px !important; color: #333333 !important; font-size: 15px !important;

    /* 左右内边距留白，防打字挡住两端按键 */
    padding-left: var(--input-padding-left) !important; 
    padding-right: var(--input-padding-right) !important; 
    flex-grow: 1 !important; animation: none !important;
}

/* --- 自定义灰色占位符提示字 --- */
.input-box-custom::placeholder, .chat-input::placeholder { 
    color: transparent !important; -webkit-text-fill-color: transparent !important; /* 隐藏系统默认提示 */
}
.input-action-bar-custom::before {
    content: var(--custom-placeholder) !important; 
    position: absolute !important; left: var(--placeholder-left) !important; top: 50% !important; transform: translateY(-50%) !important;
    color: var(--placeholder-color) !important; font-size: var(--placeholder-size) !important; 
    pointer-events: none !important; transition: opacity 0.15s ease !important; z-index: 5 !important;
}
/* 打字时灰色文字消失 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::before,
.input-action-bar-custom:has(.chat-input:not(:placeholder-shown))::before { 
    opacity: 0 !important; 
}

/* --- 底部所有功能按键全面贴纸化 --- */
.input-area-custom svg, #api-chat-screen .chat-input-area svg, .input-btn-plus svg, .toggle-tools-btn svg,
.input-btn-mic svg, .chat-action-btn svg, .input-btn-sticker svg, .input-btn-ai svg, .send-btn-custom svg, .send-button svg { 
    display: none !important; /* 斩草除根隐藏原生SVG */
}
.input-btn-plus, .toggle-tools-btn, .input-btn-mic, .chat-action-btn, .input-btn-sticker, .input-btn-ai, .send-btn-custom, .send-button {
    background-color: transparent !important; border: none !important; box-shadow: none !important;
    background-repeat: no-repeat !important; background-position: center !important; background-size: contain !important;
    flex-shrink: 0 !important; color: transparent !important; padding: 0 !important; margin: 0 !important;
}

/* 分配各按键独立贴纸图与位置 */
.input-btn-plus, .toggle-tools-btn { 
    background-image: var(--btn-plus-img) !important; width: var(--btn-plus-size) !important; height: var(--btn-plus-size) !important; transform: translate(var(--btn-plus-x), var(--btn-plus-y)) !important;
}
.input-btn-mic { 
    background-image: var(--btn-mic-img) !important; width: var(--btn-mic-size) !important; height: var(--btn-mic-size) !important; transform: translate(var(--btn-mic-x), var(--btn-mic-y)) !important;
}
.input-btn-sticker { 
    background-image: var(--btn-sticker-img) !important; width: var(--btn-sticker-size) !important; height: var(--btn-sticker-size) !important; transform: translate(var(--btn-sticker-x), var(--btn-sticker-y)) !important;
}
.input-btn-ai { 
    background-image: var(--btn-ai-img) !important; width: var(--btn-ai-size) !important; height: var(--btn-ai-size) !important; transform: translate(var(--btn-ai-x), var(--btn-ai-y)) !important; transition: opacity 0.2s !important;
}
.send-btn-custom, .send-button { 
    background-image: var(--btn-send-img) !important; width: var(--btn-send-size) !important; height: var(--btn-send-size) !important; transform: translate(var(--btn-send-x), var(--btn-send-y)) !important;
}

/* --- 动态切换魔法：打字时隐藏回复键，召唤发送键 --- */
.send-btn-custom, .send-button { display: none !important; }
.input-action-bar-custom:has(input:not(:placeholder-shown)) .input-btn-ai,
.input-action-bar-custom:has(textarea:not(:placeholder-shown)) .input-btn-ai { display: none !important; }
.input-action-bar-custom:has(input:not(:placeholder-shown)) .send-btn-custom,
.input-action-bar-custom:has(input:not(:placeholder-shown)) .send-button,
.input-action-bar-custom:has(textarea:not(:placeholder-shown)) .send-btn-custom,
.input-action-bar-custom:has(textarea:not(:placeholder-shown)) .send-button { display: block !important; }


/* ====================================================================
   █ 模块 4：气泡系统 (蕾丝恋原生粉白渐变 + 骨翼挂饰)
   ==================================================================== */
/* 🌟 核心修复：解除封印，让挂饰贴纸超出气泡限制完美展现 */
.msg-bubble-wrapper, .msg-content-stack, .msg-plain-me, .msg-plain-them, .bubble-me-custom, .bubble-them-custom {
    overflow: visible !important;
}

/* --- 气泡样式：我方发送 (右侧) --- */
.msg-plain-me, .bubble-me-custom { 
    color: #cbaeb9 !important; 
    border-radius: 12px !important; 
    padding: 6px 12px !important; 
    border: 1px solid #eadae5 !important; 
    box-shadow: 0 2px 6px rgba(0,0,0,0.08) !important; 
    position: relative !important; z-index: 1 !important; 
    background: radial-gradient(ellipse at center, #fff5f9 0%, #ffffff 70%) !important; 
}
/* 我方气泡：左侧侧边翅 */
.msg-plain-me::before, .bubble-me-custom::before { 
    content: '' !important; display: block !important;
    position: absolute !important; width: 50px !important; height: 90px !important; 
    top: -16px !important; left: -16px !important; 
    background-image: url('https://file.zhuyitai.com/feedback/202511/25/13ddff63be41f66241afcbff47f470e8.png') !important; 
    background-size: contain !important; background-repeat: no-repeat !important; 
    transform: scaleX(-1) !important; pointer-events: none !important; z-index: 2 !important; 
}
/* 我方气泡：右侧顶端结 */
.msg-plain-me::after, .bubble-me-custom::after { 
    content: '' !important; display: block !important;
    position: absolute !important; width: 50px !important; height: 50px !important; 
    top: 15px !important; right: -52px !important; transform: translateY(-50%) !important; 
    background-image: url('https://www.yn12377.cn/jubao/upload/smjb/2025/11/22/38c92d3d04714b2bafa60e2139e996ef.png') !important; 
    background-size: contain !important; background-repeat: no-repeat !important; 
