}

/* ====================================================================
   █ 模块 1：全局背景与防遮挡系统
   ==================================================================== */
/* 注入全局静态背景图 */
body, .chat-detail-screen, #api-chat-screen {
    background-image: var(--global-bg-img) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important; /* 固定背景，滑动消息时背景不动 */
    background-color: transparent !important;
}

/* 强制清理可能自带的渐变或暗色遮罩 */
.chat-detail-screen::after, .chat-detail-screen::before {
    display: none !important;
}

/* 赋予聊天容器上下留白，防止首尾消息陷入顶底栏 */
.chat-messages-area, .chat-messages, .message-list, .scroll-view,
[class*="message-list"], [class*="chat-content"], .messages-container {
    padding-top: var(--messages-padding-top) !important;
